-- ========================================================

function DebugBox:__init()
    self.controller = nil

    self.vTargetFollow = nil     -- Transform
    self.humanCharacter = nil    -- Character
    self.catCharacter = nil      -- Character
    self.humanMotor = nil        -- KinematicCharacterMotor
    self.catMotor = nil          -- KinematicCharacterMotor
    self.switchablePlayerController = nil    -- lua SwitchablePlayerController


    self.debugBoxStartButton = nil      -- DebugBoxStartButton
    self.debugBoxRestartButton = nil    -- DebugBoxRestartButton
    self.debugBoxSpeedButton = nil      -- DebugBoxSpeedButton
    self.debugBoxFrameRateButton = nil  -- DebugBoxFrameRateButton
    self.debugBoxMoveButton = nil       -- DebugBoxMoveButton
    self.mCamera = nil                  -- Camera
end


function DebugBox:__delete()
    if self.co_1 ~= nil then
        cs_coroutine.stop(self.co_1)
    end
    self.co_1 = nil
end


function DebugBox:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end



function DebugBox:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:

    self.totalCanvasGroup = KTool.GetComponent(self.controller.gameObject, typeof(CanvasGroup))
    assert( self.totalCanvasGroup )


    if DebugBox.IsTotalActive() == false then
        self:HideAll()
        return
    end

    assert( self.movePanelBH )
    self.movePanel = DreamSpaceLuaUtils.GetLuaScr(self.movePanelBH.gameObject, "Game.DreamSpace.DebugBox.DebugBoxMovePanel" )
    assert( self.movePanel )


    assert(self.debugBoxRestartButtonBH)
    self.debugBoxRestartButton = DreamSpaceLuaUtils.GetLuaScr(self.debugBoxRestartButtonBH.gameObject, "Game.DreamSpace.DebugBox.DebugBoxRestartButton" )
    assert( self.debugBoxRestartButton )
    

    assert(self.backPanelGroup and self.startBtn and self.restartBtn and self.speedBtn and self.moveBtn and self.frameRateBtn )

    -- must after Awake()
    self.mCamera = DreamSpaceCamera.GetMainCamera()
    --self.restartBtn.onClick.AddListener(OnRestart)


    self:HideAll()

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end


function DebugBox:DelayInit()

    coroutine.yield(Yielders.EndOfFrame)
    coroutine.yield(Yielders.EndOfFrame)
    
    for i = 1, DreamSpaceStates.DelayInitWaitFrames do

        self.vTargetFollow = GlobalsInDreamSpace.FindComponent("vTargetFollow")
        self.humanCharacter = GlobalsInDreamSpace.FindComponent("humanCharacter")
        self.catCharacter = GlobalsInDreamSpace.FindComponent("catCharacter")
        self.switchablePlayerControllerBH = GlobalsInDreamSpace.FindComponent("switchablePlayerControllerBH")


        if not isNull( self.vTargetFollow ) and not isNull( self.humanCharacter ) and not isNull( self.catCharacter ) and not isNull(self.switchablePlayerControllerBH) then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end
    
    if isNull( self.vTargetFollow ) or isNull( self.humanCharacter ) or isNull( self.catCharacter ) 
       or GlobalsInDreamSpace.GetStringState("MorphologyType") == "" 
       or GlobalsInDreamSpace.GetStringState("MorphologyType") == "None" then
        printError("始终没能找到 vTargetFollow or humanCharacter or catCharacter or switchablePlayerControllerBH, 请查找原因")
        return
    end

    self.switchablePlayerController = DreamSpaceLuaUtils.GetLuaScr(self.switchablePlayerControllerBH.gameObject, "Game.DreamSpace.CharacterController.SwitchablePlayerController" )

    assert( self.switchablePlayerController )
    
    self.humanMotor = KTool.GetComponent(self.humanCharacter.gameObject, typeof(KinematicCharacterMotor))
    self.catMotor = KTool.GetComponent(self.catCharacter.gameObject, typeof(KinematicCharacterMotor))
    assert(self.humanMotor ~= nil and self.catMotor ~= nil)
    
    self.movePanel:Init(self, self.humanCharacter.transform, self.catCharacter.transform, self.mCamera)
    
    self.debugBoxRestartButton:Init(self, self.restartBtn)
    self.debugBoxSpeedButton = DebugBoxSpeedButton.New(self, self.speedBtn)
    self.debugBoxFrameRateButton = DebugBoxFrameRateButton.New(self, self.frameRateBtn)
    self.debugBoxMoveButton = DebugBoxMoveButton.New(self, self.moveBtn)

    self.debugBoxStartButton = DebugBoxStartButton.New(self, self.startBtn) -- !!! Must In Last

    print("koko - debugBox 初始化完成")
end



function DebugBox:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end





-- =========================================== Self ================================================ --


function DebugBox:Update()
    if DebugBox.IsTotalActive() == false then
        return
    end
    
    if  Input.GetKeyDown(KeyCode.F12) and 
        DreamSpaceLuaUtils.IsEditorPlatform() -- 在 editor 模式;
    then 
        if self.totalCanvasGroup.interactable == true then 
            self:HideAll()
        else 
            self:ShowAll()
        end
    end

end


function DebugBox:HideAll()
    self.totalCanvasGroup.alpha = 0.0 
    self.totalCanvasGroup.interactable = false 
end 


function DebugBox:ShowAll()
    self.totalCanvasGroup.alpha = 1.0 
    self.totalCanvasGroup.interactable = true
end 



function DebugBox:OnRestart()
    print("restart -----")
end


function DebugBox:LongPress(bStart)
    if bStart then
        print("长按 true")
    else
        print("长按 false")
    end
end


function DebugBox:OpenAll()
    DebugBox.SetCanvasGroupActive( self.backPanelGroup, true )
end


function DebugBox:CloseAll()
    if self.debugBoxMoveButton:isOpen() then
        self.debugBoxMoveButton:OnPress()
    end
    
    self.debugBoxSpeedButton:Restart()
    self.debugBoxFrameRateButton:Restart()
    -- ---:
    DebugBox.SetCanvasGroupActive( self.backPanelGroup, false )
end




function DebugBox.SetCanvasGroupActive( canvasGroup_, isActive_ )
    if isActive_ == true then 
        canvasGroup_.alpha = 1.0 
        canvasGroup_.interactable = true
        canvasGroup_.blocksRaycasts = true
    else 
        canvasGroup_.alpha = 0.0
        canvasGroup_.interactable = false
        canvasGroup_.blocksRaycasts = false
    end
end



return DebugBox

